<?php

// สคริปต์ครั้งเดียว: sync ตาราง products/product_variants/categories/units ทั้งหมดจากเครื่อง local
// เข้า Railway ให้ตรงกัน (แทนที่จะพึ่ง seeder ซึ่งมีแค่ข้อมูลต้นแบบ 94 รายการเดิม)
// รัน: php sync-products.php  (จากโฟลเดอร์ /app บน Railway)
// ลบไฟล์นี้ทิ้งได้หลังรันเสร็จ ไม่ใช่ส่วนหนึ่งของแอป
//
// วิธีทำงาน: จับคู่สินค้าด้วย "ชื่อสินค้า" (ไม่ใช้ SKU เพราะ SKU ระหว่าง 2 ฐานข้อมูลไม่ตรงกัน)
// สินค้าที่มีชื่อตรงกับที่ seeder สร้างไว้แล้ว -> อัปเดตข้อมูล (คง id เดิม ไม่กระทบเอกสาร/ประวัติ
// ที่อ้างอิง id นั้นอยู่แล้วบน Railway) ส่วนสินค้าที่ไม่มีอยู่เลย -> สร้างใหม่

require __DIR__.'/vendor/autoload.php';
$app = require_once __DIR__.'/bootstrap/app.php';
$kernel = $app->make(Illuminate\Contracts\Console\Kernel::class);
$kernel->bootstrap();

$b64 = '
';

$json = base64_decode($b64);
$products = json_decode($json, true);

if ($products === null) {
    echo "ERROR: decode failed - ".json_last_error_msg()."\n";
    exit(1);
}

echo count($products)." products in payload\n";

$categoryIds = [];
$unitIds = [];
$productsUpdated = 0;
$productsCreated = 0;
$variantsSynced = 0;

foreach ($products as $row) {
    $catName = $row['category'];
    if (!isset($categoryIds[$catName])) {
        $cat = App\Models\Category::firstOrCreate(['name' => $catName]);
        $categoryIds[$catName] = $cat->id;
    }

    $unitName = $row['unit'];
    if (!isset($unitIds[$unitName])) {
        $unit = App\Models\Unit::firstOrCreate(['name' => $unitName]);
        $unitIds[$unitName] = $unit->id;
    }

    $existing = App\Models\Product::where('name', $row['name'])->first();

    $data = [
        'name' => $row['name'],
        'sku' => $row['sku'],
        'size' => $row['size'],
        'description' => $row['description'],
        'category_id' => $categoryIds[$catName],
        'unit_id' => $unitIds[$unitName],
        'cost' => $row['cost'],
        'price' => $row['price'],
        'wholesale_price' => $row['wholesale_price'],
        'online_price' => $row['online_price'],
        'stock' => $row['stock'],
        'reorder_point' => $row['reorder_point'],
        'suggested_reorder_qty' => $row['suggested_reorder_qty'],
        'active' => $row['active'],
    ];

    // เก็บรูปเดิมไว้ถ้ามีอยู่แล้วบน Railway (เช่นจาก backfill-photos.php ที่รันไปก่อนหน้า)
    // ถ้ายังไม่มี ค่อยใช้ path จากเครื่อง local
    if (empty($existing?->photo_path) && !empty($row['photo_path'])) {
        $data['photo_path'] = $row['photo_path'];
    }

    if ($existing) {
        $existing->update($data);
        $product = $existing;
        $productsUpdated++;
    } else {
        $product = App\Models\Product::create(array_merge(['sku' => $row['sku']], $data));
        $productsCreated++;
    }

    // sync variants: ลบของเดิมที่ผูกกับสินค้านี้แล้วสร้างใหม่ตามชุดจากเครื่อง local
    $product->variants()->delete();
    foreach ($row['variants'] as $v) {
        $product->variants()->create([
            'label' => $v['label'],
            'unit_qty' => $v['unit_qty'],
            'price' => $v['price'],
            'online_price' => $v['online_price'],
            'sort_order' => $v['sort_order'],
        ]);
        $variantsSynced++;
    }
}

echo "categories: ".count($categoryIds)."\n";
echo "units: ".count($unitIds)."\n";
echo "products updated: {$productsUpdated}\n";
echo "products created: {$productsCreated}\n";
echo "variants synced: {$variantsSynced}\n";
echo "DONE\n";
